from pathlib import Path


def read(path: str) -> str:
    return Path(path).read_text()


def write(path: str, content: str) -> None:
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(content)


def replace_once(path: str, before: str, after: str) -> None:
    content = read(path)
    count = content.count(before)
    if count != 1:
        raise RuntimeError(f"Expected one anchor in {path}, found {count}: {before[:160]!r}")
    write(path, content.replace(before, after, 1))


write(
    "src/core/commentBodies.ts",
    '''import type { EditorBlockNode } from "./model.js";\nimport { getParagraphText } from "./model.js";\n\nfunction blockText(block: EditorBlockNode): string {\n  if (block.type === "paragraph") {\n    return getParagraphText(block);\n  }\n  return block.rows\n    .map((row): string =>\n      row.cells\n        .map((cell): string => getCommentBlocksText(cell.blocks))\n        .join("\\t"),\n    )\n    .join("\\n");\n}\n\n/** Plain-text projection used by comment UI and compatibility APIs. */\nexport function getCommentBlocksText(blocks: EditorBlockNode[]): string {\n  return blocks.map(blockText).join("\\n");\n}\n''',
)

write(
    "src/core/model/types/documentComments.ts",
    '''/**\n * Comment registry (Word's `w:commentRangeStart` / `w:commentRangeEnd` /\n * `w:commentReference` + the `word/comments.xml` bodies).\n *\n * A comment is two independent things glued by a shared id:\n *  - a *range* over document text, modeled like a bookmark; and\n *  - an out-of-band body in `word/comments.xml`, modeled as the same block tree\n *    used by document/notes when rich content is available.\n *\n * `text` remains the compatibility/UI projection. Imported rich `blocks` are\n * exported while that projection is unchanged; callers that edit only `text`\n * still get the historical plain-text comment behavior.\n */\nimport type { EditorBlockNode } from "./nodes.js";\n\nexport interface EditorCommentAnchor {\n  /** Id of the paragraph this anchor lives in (`EditorParagraphNode.id`). */\n  paragraphId: string;\n  /** Character offset into the paragraph's flattened text stream. */\n  offset: number;\n  /** Stable ordering hint for boundaries sharing one offset. */\n  seq?: number;\n}\n\nexport interface EditorComment {\n  /** Stable editor-local id (not the DOCX `w:id`). */\n  id: string;\n  /** Original DOCX `w:id`, used only as a hint for export id stability. */\n  docxIdHint?: number;\n  /** `w:comment/@w:author`. */\n  author: string;\n  /** `w:comment/@w:initials`. */\n  initials?: string;\n  /** `w:comment/@w:date` as an epoch millisecond timestamp. */\n  date?: number;\n  /** `w16du:dateUtc` companion UTC timestamp (epoch ms). */\n  dateUtc?: number;\n  /** Resolved/"done" state (`w15:commentEx/@w15:done`). */\n  resolved?: boolean;\n  /** Editor-local parent comment id for a threaded reply (`w15:paraIdParent`). */\n  parentId?: string;\n  /** Plain-text projection used by current comment UI and compatibility APIs. */\n  text: string;\n  /** Rich block body parsed from `word/comments.xml` when available. */\n  blocks?: EditorBlockNode[];\n  /** Start anchor. May be absent for a malformed import (orphan end). */\n  start?: EditorCommentAnchor;\n  /** End anchor. May be absent for a malformed import (orphan start). */\n  end?: EditorCommentAnchor;\n}\n\nexport interface EditorComments {\n  items: Record<string, EditorComment>;\n  /** Stable creation/import order for deterministic export. */\n  order: string[];\n}\n''',
)

write(
    "src/import/docx/commentsXml.ts",
    '''/** Parse comment bodies and modern thread metadata from DOCX parts. */\nimport { DOMParser, type Element as XmlElement } from "@xmldom/xmldom";\nimport type { EditorBlockNode } from "@/core/model.js";\nimport { getCommentBlocksText } from "@/core/commentBodies.js";\nimport {\n  WORD_NS,\n  getChildrenByTagNameNS,\n  getAttributeValue,\n} from "./xmlHelpers.js";\n\nconst WORD15_NS = "http://schemas.microsoft.com/office/word/2012/wordml";\nconst WORD16DU_NS =\n  "http://schemas.microsoft.com/office/word/2023/wordml/word16du";\n\nexport interface ParsedCommentBody {\n  author: string;\n  initials?: string;\n  date?: number;\n  dateUtc?: number;\n  text: string;\n  blocks?: EditorBlockNode[];\n  resolved?: boolean;\n  /** `w14:paraId` of the first comment paragraph; links to commentsEx. */\n  paraId?: string;\n  /** Parent comment paragraph id from `w15:commentEx/@w15:paraIdParent`. */\n  parentParaId?: string;\n}\n\nexport type ParseCommentBlocks = (\n  container: XmlElement,\n) => Promise<EditorBlockNode[]>;\n\nfunction flattenCommentText(element: XmlElement): string {\n  let out = "";\n  for (let index = 0; index < element.childNodes.length; index += 1) {\n    const node = element.childNodes[index];\n    if (node?.nodeType !== node.ELEMENT_NODE) continue;\n    const child = node as XmlElement;\n    if (child.namespaceURI === WORD_NS) {\n      if (child.localName === "t") {\n        out += child.textContent ?? "";\n        continue;\n      }\n      if (child.localName === "tab") {\n        out += "\\t";\n        continue;\n      }\n      if (child.localName === "br" || child.localName === "cr") {\n        out += "\\n";\n        continue;\n      }\n    }\n    out += flattenCommentText(child);\n  }\n  return out;\n}\n\nfunction parseDate(value: string | null): number | undefined {\n  if (!value) return undefined;\n  const ms = Date.parse(value);\n  return Number.isNaN(ms) ? undefined : ms;\n}\n\ninterface ParsedCommentExtended {\n  resolved: boolean;\n  parentParaId?: string;\n}\n\nfunction parseCommentsExtended(\n  xml: string | null,\n): Map<string, ParsedCommentExtended> {\n  const extended = new Map<string, ParsedCommentExtended>();\n  if (!xml) return extended;\n  const doc = new DOMParser().parseFromString(xml, "application/xml");\n  const root = doc.documentElement;\n  if (!root) return extended;\n  for (const ex of getChildrenByTagNameNS(root, WORD15_NS, "commentEx")) {\n    const paraId = ex.getAttributeNS(WORD15_NS, "paraId");\n    if (!paraId) continue;\n    const isDone = ex.getAttributeNS(WORD15_NS, "done");\n    const parentParaId =\n      ex.getAttributeNS(WORD15_NS, "paraIdParent") || undefined;\n    extended.set(paraId, {\n      resolved: isDone === "1" || isDone === "true",\n      ...(parentParaId ? { parentParaId } : {}),\n    });\n  }\n  return extended;\n}\n\nexport async function parseCommentsXml(\n  commentsXml: string | null,\n  commentsExtendedXml: string | null,\n  parseBlocks?: ParseCommentBlocks,\n): Promise<Map<string, ParsedCommentBody>> {\n  const byDocxId = new Map<string, ParsedCommentBody>();\n  if (!commentsXml) return byDocxId;\n  const doc = new DOMParser().parseFromString(commentsXml, "application/xml");\n  const root = doc.documentElement;\n  if (!root) return byDocxId;\n\n  const extendedByParaId = parseCommentsExtended(commentsExtendedXml);\n\n  for (const comment of getChildrenByTagNameNS(root, WORD_NS, "comment")) {\n    const docxId = getAttributeValue(comment, "id");\n    if (docxId === null) continue;\n    const author = getAttributeValue(comment, "author") ?? "";\n    const initials = getAttributeValue(comment, "initials") ?? undefined;\n    const date = parseDate(getAttributeValue(comment, "date"));\n    const dateUtc = parseDate(comment.getAttributeNS(WORD16DU_NS, "dateUtc"));\n    const paragraphs = getChildrenByTagNameNS(comment, WORD_NS, "p");\n    const parsedBlocks = parseBlocks ? await parseBlocks(comment) : undefined;\n    const blocks =\n      parsedBlocks && parsedBlocks.length > 0 ? parsedBlocks : undefined;\n    const text = blocks\n      ? getCommentBlocksText(blocks)\n      : paragraphs.map((p): string => flattenCommentText(p)).join("\\n").trim();\n    const paraId =\n      paragraphs.length > 0\n        ? (getAttributeValue(paragraphs[0]!, "paraId") ?? undefined)\n        : undefined;\n    const extended = paraId ? extendedByParaId.get(paraId) : undefined;\n\n    byDocxId.set(docxId, {\n      author,\n      ...(initials ? { initials } : {}),\n      ...(date !== undefined ? { date } : {}),\n      ...(dateUtc !== undefined ? { dateUtc } : {}),\n      text,\n      ...(blocks ? { blocks } : {}),\n      ...(extended?.resolved ? { resolved: true } : {}),\n      ...(paraId ? { paraId } : {}),\n      ...(extended?.parentParaId\n        ? { parentParaId: extended.parentParaId }\n        : {}),\n    });\n  }\n\n  return byDocxId;\n}\n''',
)

