write(
    "src/export/docx/commentsXml.ts",
    '''/** Comment range planning plus rich `word/comments.xml` serialization. */\nimport type {\n  EditorBlockNode,\n  EditorComment,\n  EditorDocument,\n  EditorNamedStyle,\n} from "@/core/model.js";\nimport { getCommentBlocksText } from "@/core/commentBodies.js";\nimport type { DocContext } from "./docxTypes.js";\nimport { serializeBlocksXml } from "./textXml.js";\nimport {\n  escapeXml,\n  OFFICE_REL_NS,\n  WORD_NS,\n  WORD14_NS,\n} from "./xmlUtils.js";\n\nconst WORD15_NS = "http://schemas.microsoft.com/office/word/2012/wordml";\nconst WORD16DU_NS =\n  "http://schemas.microsoft.com/office/word/2023/wordml/word16du";\n\nexport interface CommentBoundaryEvent {\n  kind: "start" | "end" | "reference";\n  offset: number;\n  seq: number;\n  wId: number;\n}\n\nexport type CommentEventsByParagraph = Map<string, CommentBoundaryEvent[]>;\n\ninterface AssignedComment {\n  comment: EditorComment;\n  wId: number;\n  paraId: string;\n}\n\nexport interface CommentExportPlan {\n  eventsByParagraph: CommentEventsByParagraph;\n  comments: AssignedComment[];\n}\n\nexport function buildCommentExportPlan(\n  document: EditorDocument,\n): CommentExportPlan | undefined {\n  const registry = document.comments;\n  if (!registry || registry.order.length === 0) return undefined;\n\n  const assignedId = new Map<string, number>();\n  const used = new Set<number>();\n  for (const id of registry.order) {\n    const comment = registry.items[id];\n    if (!comment) continue;\n    const hint = comment.docxIdHint;\n    if (hint !== undefined && hint >= 0 && !used.has(hint)) {\n      assignedId.set(id, hint);\n      used.add(hint);\n    }\n  }\n  let next = 0;\n  for (const id of registry.order) {\n    if (assignedId.has(id)) continue;\n    while (used.has(next)) next += 1;\n    assignedId.set(id, next);\n    used.add(next);\n    next += 1;\n  }\n\n  const eventsByParagraph: CommentEventsByParagraph = new Map();\n  const push = (paragraphId: string, event: CommentBoundaryEvent): void => {\n    const list = eventsByParagraph.get(paragraphId);\n    if (list) list.push(event);\n    else eventsByParagraph.set(paragraphId, [event]);\n  };\n\n  const comments: AssignedComment[] = [];\n  registry.order.forEach((id, index): void => {\n    const comment = registry.items[id];\n    if (!comment) return;\n    const wId = assignedId.get(id)!;\n    const paraId = (0x40000000 + index).toString(16).toUpperCase();\n    comments.push({ comment, wId, paraId });\n    if (comment.start) {\n      push(comment.start.paragraphId, {\n        kind: "start",\n        offset: comment.start.offset,\n        seq: comment.start.seq ?? 0,\n        wId,\n      });\n    }\n    if (comment.end) {\n      push(comment.end.paragraphId, {\n        kind: "end",\n        offset: comment.end.offset,\n        seq: comment.end.seq ?? 0,\n        wId,\n      });\n      push(comment.end.paragraphId, {\n        kind: "reference",\n        offset: comment.end.offset,\n        seq: (comment.end.seq ?? 0) + 0.5,\n        wId,\n      });\n    }\n  });\n  return { eventsByParagraph, comments };\n}\n\nexport function serializeCommentRangeEvent(\n  event: CommentBoundaryEvent,\n): string {\n  switch (event.kind) {\n    case "start":\n      return `<w:commentRangeStart w:id="${event.wId}"/>`;\n    case "end":\n      return `<w:commentRangeEnd w:id="${event.wId}"/>`;\n    case "reference":\n      return `<w:r><w:commentReference w:id="${event.wId}"/></w:r>`;\n  }\n}\n\nconst COMMENTS_XMLNS =\n  `xmlns:w="${WORD_NS}" xmlns:w14="${WORD14_NS}" ` +\n  `xmlns:w15="${WORD15_NS}" xmlns:w16du="${WORD16DU_NS}" ` +\n  `xmlns:r="${OFFICE_REL_NS}" ` +\n  'xmlns:wp="http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing" ' +\n  'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" ' +\n  'xmlns:pic="http://schemas.openxmlformats.org/drawingml/2006/picture" ' +\n  'xmlns:wps="http://schemas.microsoft.com/office/word/2010/wordprocessingShape"';\n\nfunction serializeCommentBody(text: string): string {\n  const lines = text.split("\\n");\n  const runs = lines\n    .map((line, index): string => {\n      const brk = index > 0 ? "<w:br/>" : "";\n      return `${brk}<w:t xml:space="preserve">${escapeXml(line)}</w:t>`;\n    })\n    .join("");\n  return `<w:r>${runs}</w:r>`;\n}\n\nfunction richBlocksForExport(comment: EditorComment): EditorBlockNode[] | undefined {\n  return comment.blocks && getCommentBlocksText(comment.blocks) === comment.text\n    ? comment.blocks\n    : undefined;\n}\n\nexport function collectCommentBodyBlocksForExport(\n  plan: CommentExportPlan,\n): EditorBlockNode[] {\n  return plan.comments.flatMap(({ comment }): EditorBlockNode[] =>\n    richBlocksForExport(comment) ?? [],\n  );\n}\n\nfunction stampFirstParagraphParaId(xml: string, paraId: string): string {\n  const paragraph = /<w:p\\b([^>]*)>/;\n  if (!paragraph.test(xml)) {\n    return `<w:p w14:paraId="${paraId}"/>${xml}`;\n  }\n  return xml.replace(paragraph, (_match, rawAttrs: string): string => {\n    const attrs = rawAttrs.replace(/\\s+w14:paraId="[^"]*"/g, "");\n    return `<w:p${attrs} w14:paraId="${paraId}">`;\n  });\n}\n\nexport function buildCommentsPartXml(\n  plan: CommentExportPlan,\n  context?: DocContext,\n  styles?: Record<string, EditorNamedStyle>,\n): string {\n  const body = plan.comments\n    .map(({ comment, wId, paraId }): string => {\n      const dateAttr =\n        comment.date !== undefined\n          ? ` w:date="${new Date(comment.date).toISOString().replace(/\\.\\d{3}Z$/, "Z")}"`\n          : "";\n      const dateUtcAttr =\n        comment.dateUtc !== undefined\n          ? ` w16du:dateUtc="${new Date(comment.dateUtc).toISOString().replace(/\\.\\d{3}Z$/, "Z")}"`\n          : "";\n      const initialsAttr = comment.initials\n        ? ` w:initials="${escapeXml(comment.initials)}"`\n        : "";\n      const richBlocks = richBlocksForExport(comment);\n      const bodyXml =\n        richBlocks && context\n          ? stampFirstParagraphParaId(\n              serializeBlocksXml(richBlocks, context, styles),\n              paraId,\n            )\n          : `<w:p w14:paraId="${paraId}">${serializeCommentBody(comment.text)}</w:p>`;\n      return (\n        `<w:comment w:id="${wId}" w:author="${escapeXml(comment.author)}"${dateAttr}${dateUtcAttr}${initialsAttr}>` +\n        `${bodyXml}</w:comment>`\n      );\n    })\n    .join("");\n  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:comments ${COMMENTS_XMLNS}>${body}</w:comments>`;\n}\n\nexport function buildCommentsExtendedPartXml(plan: CommentExportPlan): string {\n  const paraIdByCommentId = new Map(\n    plan.comments.map(({ comment, paraId }) => [comment.id, paraId] as const),\n  );\n  const body = plan.comments\n    .map(({ comment, paraId }): string => {\n      const parentParaId = comment.parentId\n        ? paraIdByCommentId.get(comment.parentId)\n        : undefined;\n      const parentAttr = parentParaId\n        ? ` w15:paraIdParent="${parentParaId}"`\n        : "";\n      return `<w15:commentEx w15:paraId="${paraId}"${parentAttr} w15:done="${comment.resolved ? "1" : "0"}"/>`;\n    })\n    .join("");\n  return `<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w15:commentsEx ${COMMENTS_XMLNS}>${body}</w15:commentsEx>`;\n}\n''',
)

