write(
    "tests/vitest/__tests__/import/docxImport.richComments.test.ts",
    '''import { describe, expect, it } from "vitest";\nimport JSZip from "jszip";\nimport type { EditorParagraphNode } from "@/core/model.js";\nimport { importDocxToEditorDocument } from "@/import/docx/importDocxToEditorDocument.js";\nimport { exportEditorDocumentToDocx } from "@/export/docx/exportEditorDocumentToDocx.js";\n\nconst W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";\nconst R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";\nconst W14 = "http://schemas.microsoft.com/office/word/2010/wordml";\nconst PKG = "http://schemas.openxmlformats.org/package/2006/relationships";\n\nasync function buildRichCommentDocx(): Promise<ArrayBuffer> {\n  const zip = new JSZip();\n  zip.file(\n    "word/document.xml",\n    `<w:document xmlns:w="${W}"><w:body><w:p><w:commentRangeStart w:id="4"/><w:r><w:t>Target</w:t></w:r><w:commentRangeEnd w:id="4"/><w:r><w:commentReference w:id="4"/></w:r></w:p><w:sectPr/></w:body></w:document>`,\n  );\n  zip.file(\n    "word/comments.xml",\n    `<w:comments xmlns:w="${W}" xmlns:w14="${W14}" xmlns:r="${R}"><w:comment w:id="4" w:author="Rich"><w:p w14:paraId="ABCDEF01"><w:r><w:rPr><w:b/></w:rPr><w:t>Bold</w:t></w:r></w:p><w:p><w:hyperlink r:id="rIdWeb"><w:r><w:rPr><w:i/></w:rPr><w:t>Link</w:t></w:r></w:hyperlink></w:p></w:comment></w:comments>`,\n  );\n  zip.file(\n    "word/_rels/comments.xml.rels",\n    `<Relationships xmlns="${PKG}"><Relationship Id="rIdWeb" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink" Target="https://example.com/rich" TargetMode="External"/></Relationships>`,\n  );\n  return zip.generateAsync({ type: "arraybuffer" });\n}\n\nfunction onlyComment(document: Awaited<ReturnType<typeof importDocxToEditorDocument>>) {\n  const registry = document.comments!;\n  return registry.items[registry.order[0]!]!;\n}\n\ndescribe("DOCX rich comment bodies", () => {\n  it("imports comment paragraphs through the normal block/run pipeline", async () => {\n    const document = await importDocxToEditorDocument(await buildRichCommentDocx());\n    const comment = onlyComment(document);\n    expect(comment.text).toBe("Bold\\nLink");\n    expect(comment.blocks).toHaveLength(2);\n    const first = comment.blocks![0] as EditorParagraphNode;\n    const second = comment.blocks![1] as EditorParagraphNode;\n    expect(first.runs[0]!.styles?.bold).toBe(true);\n    expect(second.runs[0]!.styles?.italic).toBe(true);\n    expect(second.runs[0]!.styles?.link).toBe("https://example.com/rich");\n  });\n\n  it("exports rich paragraphs with comments-part relationships and reimports them", async () => {\n    const document = await importDocxToEditorDocument(await buildRichCommentDocx());\n    const exported = await exportEditorDocumentToDocx(document);\n    const zip = await JSZip.loadAsync(exported);\n    const xml = (await zip.file("word/comments.xml")?.async("string")) ?? "";\n    const rels =\n      (await zip.file("word/_rels/comments.xml.rels")?.async("string")) ?? "";\n\n    expect((xml.match(/<w:p\\b/g) ?? []).length).toBe(2);\n    expect(xml).toContain("<w:b/>");\n    expect(xml).toContain("<w:i/>");\n    expect(xml).toContain("<w:hyperlink r:id=\"rIdLink1\">");\n    expect(xml).toContain('w14:paraId="40000000"');\n    expect(rels).toContain('Target="https://example.com/rich"');\n\n    const reimported = await importDocxToEditorDocument(exported);\n    const comment = onlyComment(reimported);\n    expect(comment.text).toBe("Bold\\nLink");\n    expect(comment.blocks).toHaveLength(2);\n    expect(\n      (comment.blocks![1] as EditorParagraphNode).runs[0]!.styles?.link,\n    ).toBe("https://example.com/rich");\n  });\n\n  it("falls back to canonical plain text when the compatibility projection is edited", async () => {\n    const document = await importDocxToEditorDocument(await buildRichCommentDocx());\n    onlyComment(document).text = "Edited body";\n    const exported = await exportEditorDocumentToDocx(document);\n    const zip = await JSZip.loadAsync(exported);\n    const xml = (await zip.file("word/comments.xml")?.async("string")) ?? "";\n    expect(xml).toContain("Edited body");\n    expect(xml).not.toContain("<w:b/>");\n    expect(xml).not.toContain("<w:hyperlink");\n    expect(zip.file("word/_rels/comments.xml.rels")).toBeNull();\n  });\n});\n''',
)

print("Applied rich comment body import/export support.")
